/** What Karwan does, where it lives and how to do it, checked against source.
 * Every page, endpoint and tool named here is verified by platformGuide.test.ts,
 * so the assistant cannot cite a screen or API that does not exist. Status is
 * repository behaviour per network; live account truth still comes from tools.
 */
export const GUIDE_REVIEWED_AT = '2026-11-05';

export const PRODUCT_LANGUAGE_RULES = "Use request for a buyer’s posted need, and offer for a seller’s listing or response. An order is managed as a deal after it is placed; call the terms agreed terms. A payment request is a link for a direct account payment, outside deal escrow, and is distinct from a buyer request. Use trade record in ordinary navigation; credit passport is a specialist or technical name. Explain a milestone as a stage with its own delivery and payment when first needed. A review button opens a reversible step; acceptance or funding requires the final confirmation. Say Not now when dismissing a sheet and Cancel deal or Cancel request only for the actual cancellation. Keep internal tool names, payloads and routes unchanged. Answer in the person’s language.";

export type GuideStatus = 'testnet' | 'gated' | 'planned';
/// invite: accounts and wallets by invitation. off: built but not enabled on
/// mainnet. planned: not built for mainnet yet.
export type MainnetStatus = 'invite' | 'off' | 'planned';

export interface GuideEntry {
  id: string;
  title: string;
  status: GuideStatus;
  mainnet: MainnetStatus;
  /// Primary screen.
  route: string;
  /// Other screens for this job.
  pages: readonly string[];
  /// `METHOD /path` endpoints the feature runs on.
  api: readonly string[];
  /// Assistant tools that read or act on it.
  tools: readonly string[];
  keywords: string;
  summary: string;
  /// How a person does it in the app, in order.
  steps: readonly string[];
  sources: readonly string[];
}

